<?php require_once __DIR__.'/../config/config.php';require_admin();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$photo='';if(!empty($_FILES['photo']['name'])&&is_uploaded_file($_FILES['photo']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['photo']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true))throw new Exception('عکس باید JPG، PNG یا WEBP باشد.');$photo=uniqid('student_',true).'.'.$ext;if(!move_uploaded_file($_FILES['photo']['tmp_name'],__DIR__.'/../uploads/'.$photo))throw new Exception('آپلود عکس انجام نشد.');}$n=(int)$pdo->query("SELECT COALESCE(MAX(CAST(student_code AS UNSIGNED)),0) FROM students WHERE student_code REGEXP '^[0-9]+$'")->fetchColumn()+1; $requested=trim($_POST['student_code']??''); if($requested!==''){$code=$requested;$chk=$pdo->prepare('SELECT COUNT(*) FROM students WHERE student_code=?');$chk->execute([$code]);if((int)$chk->fetchColumn()>0)throw new Exception('این شماره ID قبلاً استفاده شده است.');} else { do{$code=str_pad((string)$n,2,'0',STR_PAD_LEFT);$n++;$chk=$pdo->prepare('SELECT COUNT(*) FROM students WHERE student_code=?');$chk->execute([$code]);}while((int)$chk->fetchColumn()>0);}$st=$pdo->prepare('INSERT INTO students(student_code,first_name,father_name,guardian_phone,course_type,class_level,study_time,course_number,photo) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$code,trim($_POST['first_name']),trim($_POST['father_name']),trim($_POST['guardian_phone']),$_POST['course_type'],trim($_POST['class_level']),$_POST['study_time'],'',$photo]);$id=(int)$pdo->lastInsertId();$course='ARZO-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE students SET course_number=? WHERE id=?')->execute([$course,$id]);header('Location:../cards/student.php?id='.$id);exit;}catch(Exception $e){$err=$e->getMessage();}}
$nextStudentNo=(int)$pdo->query("SELECT COALESCE(MAX(CAST(student_code AS UNSIGNED)),0) FROM students WHERE student_code REGEXP '^[0-9]+$'")->fetchColumn()+1; $studentNoPreview=str_pad((string)$nextStudentNo,2,'0',STR_PAD_LEFT);require '../partials/header.php';?><div class="panel form-panel"><div class="section-title"><div><h2>ثبت دانش‌آموز</h2><span class="muted">پس از ثبت، کارت دانش‌آموز به‌صورت خودکار ساخته می‌شود.</span></div></div><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="row"><label>شماره دانشجویی<input value="<?=h($_POST['student_code']??$studentNoPreview)?>"><input type="hidden" name="student_code_preview" value="<?=h($studentNoPreview)?>"></label><label>اسم دانش‌آموز *<input required name="first_name"></label><label>اسم پدر<input name="father_name"></label><label>شماره ولی دانش‌آموز *<input required name="guardian_phone" inputmode="tel"></label><label>نوع صنف *<select name="course_type" required><option value="صنف درسی" <?=($_POST['course_type']??'صنف درسی')==='صنف درسی'?'selected':''?>>صنف درسی</option><option value="حرفه خیاطی" <?=($_POST['course_type']??'صنف درسی')==='حرفه خیاطی'?'selected':''?>>صنف حرفه‌ای خیاطی</option></select></label><label>درجه صنف<input name="class_level"></label><label>تایم درسی *<select name="study_time"><option>تایم اول</option><option>تایم دوم</option></select></label><label>عکس دانش‌آموز<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label></div><div class="actions"><button>ثبت و ساخت کارت</button><a class="btn secondary" href="index.php">بازگشت</a></div></form></div><?php require '../partials/footer.php';?>
